/**
 * The animated "still working" mark — a React Native port of the desktop's
 * `src/ui/thinking.rs`. The same four layers under
 * `assets/icons/goddard-thinking-*.svg` are stacked at full size, and the
 * source's SMIL sway, head toss, ear twitches, and blink are replayed on a
 * UI-thread frame clock as per-layer transforms.
 *
 * The source's blink slides a pair of lid rects over each eye, clipped to the
 * eye shape. The eyes are holes in the face path and everything is one color,
 * so covering an eye reads identically to painting it: the eyes layer fades
 * in on the lids' timing instead. Under reduce-motion the clock holds every
 * track at its first frame — the mark sits still, eyes open.
 */
import { useEffect } from 'react';
import { StyleSheet, View, type ViewStyle } from 'react-native';
import Animated, {
  type AnimatedStyle,
  useAnimatedStyle,
  useDerivedValue,
  useFrameCallback,
  useSharedValue,
} from 'react-native-reanimated';
import { Path, Svg } from 'react-native-svg';

import { useReducedMotion } from '@/hooks/use-reduced-motion';

/** Rendered size of the mark. The source viewBox is `-10 -10 160 125`; its
 * margin leaves room for the sway, so the drawn face fills ~84% of the box. */
const WIDTH = 28;
const HEIGHT = (WIDTH * 125) / 160;
const CENTER_X = WIDTH / 2;
const CENTER_Y = HEIGHT / 2;
const VIEW_BOX = '-10 -10 160 125';

/** Element px per viewBox unit; the viewBox's (-10, -10) min puts user-space
 * point `u` at `(u + 10) * UNITS_TO_PX`. */
const UNITS_TO_PX = WIDTH / 160;

type Track = ReadonlyArray<readonly [number, number]>;
type Pivot = readonly [number, number];

